    console.log(longestSubstring("bbbbb") === 1); // "b"
    console.log(longestSubstring("pwwkew") === 3); // "wke" or "kew"

    // Edge cases
    console.log(longestSubstring("") === 0); // Empty string
    console.log(longestSubstring(" ") === 1); // Space
    console.log(longestSubstring("  ") === 1); // Two spaces
    console.log(longestSubstring("a") === 1); // Single character
    console.log(longestSubstring("au") === 2); // Two unique characters

    // Mixed case
    console.log(longestSubstring("aA") === 2); // Case sensitive
    console.log(longestSubstring("a b") === 3); // Space and letters
    console.log(longestSubstring("a!b") === 3); // Punctuation

    // Unicode cases (UTF-16 code units)
    console.log(longestSubstring("😊😊") === 1); // Duplicate emoji
    console.log(longestSubstring("😊a") === 2); // Emoji and letter
    console.log(longestSubstring("😊😋") === 2); // Two different emojis

    // Combining marks (UTF-16 code units)
    console.log(longestSubstring("e\u0301") === 1); // e + combining acute accent
    console.log(longestSubstring("e\u0301a") === 2); // e+accent and a

    // Supplementary emoji (surrogate pairs)
    console.log(longestSubstring("👨‍👩‍👧‍👦") === 1); // Family emoji (sequence of surrogate pairs)
    console.log(longestSubstring("👨‍👩‍👧‍👦a") === 2); // Family emoji and letter

    return "All tests passed!";
}

console.log(testLongestSubstring());
```

## Unicode Handling Explanation

### UTF-16 Code Units vs. Unicode Code Points vs. Grapheme Clusters

1. **UTF-16 Code Units**:
   - JavaScript strings are sequences of UTF-16 code units
   - Each character is represented by 1 or 2 code units (16-bit values)
   - Basic Multilingual Plane (BMP) characters use 1 code unit
   - Supplementary characters (like many emojis) use 2 code units (surrogate pairs)
   - `string.length` returns the number of UTF-16 code units
   - Accessing by index (`s[i]`) gives you a UTF-16 code unit

2. **Unicode Code Points**:
   - Abstract characters in the Unicode standard
   - Range from U+0000 to U+10FFFF
   - Can be represented by 1 (BMP) or 2 (supplementary) UTF-16 code units
   - To get code points from UTF-16, you need to handle surrogate pairs

3. **User-Perceived Grapheme Clusters**:
   - What users perceive as a single character
   - Can consist of multiple Unicode code points
   - Examples: 
     - Base character + combining marks (e + acute accent = é)
     - Emoji with modifiers (skin tone, gender)
     - Emoji sequences (family emoji, flags)
     - ZWJ sequences (flag emoji)
   - The Intl.Segmenter API can properly identify grapheme clusters

### Supporting User-Perceived Characters

To properly handle grapheme clusters, we would need to modify our approach:

```js path=grapheme-aware.js
function longestSubstringGraphemeAware(s) {
    if (s.length === 0) return 0;

    // Check if Intl.Segmenter is available
    if (!Intl.Segmenter) {
        console.warn("Intl.Segmenter not available. Falling back to code unit handling.");
        return longestSubstring(s);
    }

    const segmenter = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
    const segments = segmenter.segment(s);
    const graphemes = Array.from(segments).map(s => s.segment);

    const graphemeSet = new Set();
    let left = 0;
    let maxLength = 0;

    for (let right = 0; right < graphemes.length; right++) {
        const currentGrapheme = graphemes[right];

        // If grapheme is already in the set, move left pointer to exclude it
        while (graphemeSet.has(currentGrapheme)) {
            graphemeSet.delete(graphemes[left]);
            left++;
        }

        // Add current grapheme to the set and update max length
        graphemeSet.add(currentGrapheme);
        maxLength = Math.max(maxLength, right - left + 1);
    }

    return maxLength;
}
```

**Runtime Support Policy**:
- The Intl.Segmenter API is available in modern browsers (Chrome 87+, Firefox 91+, Safari 14.1+)
- In Node.js, it's available from v16.0.0
- For environments without Intl.Segmenter, we fall back to UTF-16 code unit handling
- We should document this limitation and potential inaccuracies with complex grapheme clusters

### Why Same Unit Comparison Matters

When comparing brute-force and optimized implementations:

1. **Consistency**: Both implementations must measure length in the same unit to ensure a fair comparison
2. **Correctness**: A brute-force approach using grapheme clusters might be O(n²) in the worst case, while an optimized sliding window using UTF-16 code units might appear O(n) but actually be O(m²) where m is the number of grapheme clusters
3. **Performance**: The actual performance depends on the unit being measured - counting UTF-16 code units is faster than properly identifying grapheme clusters

For example:
- A string with 10 BMP characters: 10 code units, 10 code points, 10 grapheme clusters
- A string with 5 emoji (each using surrogate pairs): 10 code units, 5 code points, 5 grapheme clusters
- A string with 5 base characters + 5 combining marks: 10 code units, 10 code points, 5 grapheme clusters

The optimized sliding window using UTF-16 code units would run in O(n) time where n is the number of code units, but this doesn't accurately represent the complexity when dealing with grapheme clusters.

I'll implement `isValidBrackets` with explicit requirements and comprehensive testing.

### Requirements:
1. Return `true` if all brackets are properly matched and nested
2. Return `false` if brackets are mismatched, unbalanced, or improperly nested
3. Ignore non-bracket characters
4. Handle empty string as valid
5. Handle non-string inputs appropriately
6. O(n) time complexity
7. O(n) worst-case space complexity (when all characters are opening brackets)

```js
/**
 * Checks if a string has valid bracket pairs: (), [], {}
 * Non-bracket characters are ignored.
 * @param {string} s - Input string to validate
 * @returns {boolean} - True if brackets are valid, false otherwise
 */
function isValidBrackets(s) {
    // Handle non-string inputs
    if (typeof s !== 'string') {
        return false;
    }

    const stack = [];
    const bracketPairs = {
        '(': ')',
        '[': ']',
        '{': '}'
    };

    for (let i = 0; i < s.length; i++) {
        const char = s[i];

        // If it's an opening bracket, push to stack
        if (bracketPairs.hasOwnProperty(char)) {
            stack.push(char);
        } 
        // If it's a closing bracket
        else if (char === ')' || char === ']' || char === '}') {
            // If stack is empty, there's no matching opening bracket
            if (stack.length === 0) {
                return false;
            }

            // Pop the last opening bracket from stack
            const lastOpening = stack.pop();

            // Check if it matches the current closing bracket
            if (bracketPairs[lastOpening] !== char) {
                return false;
            }
        }
        // Non-bracket characters are ignored
    }

    // If stack is empty, all brackets were properly closed
    return stack.length === 0;
}
```

### Test Cases:

```js
// Test cases
function testIsValidBrackets() {
    // Valid cases
    console.log(isValidBrackets("") === true); // Empty string
    console.log(isValidBrackets("abc") === true); // Only non-bracket characters
    console.log(isValidBrackets("()") === true); // Simple valid
    console.log(isValidBrackets("[]") === true); // Simple valid
    console.log(isValidBrackets("{}") === true); // Simple valid
    console.log(isValidBrackets("(a[b]c{d}e)") === true); // Mixed with non-brackets
    console.log(isValidBrackets("([{}])") === true); // Nested
    console.log(isValidBrackets("([]){}") === true); // Multiple groups
    console.log(isValidBrackets("a(b[c]d{e}f)g[h]i{j}k") === true); // Complex with non-brackets

    // Invalid cases
    console.log(isValidBrackets("(") === false); // Unclosed opening
    console.log(isValidBrackets(")") === false); // Extra closing
    console.log(isValidBrackets("(]") === false); // Mismatched
    console.log(isValidBrackets("([)]") === false); // Improperly nested
    console.log(isValidBrackets("({)}") === false); // Improperly nested
    console.log(isValidBrackets("((())") === false); // Unclosed opening
    console.log(isValidBrackets("((())") === false); // Unclosed opening
    console.log(isValidBrackets("((())))") === false); // Extra closing

    // Non-string inputs
    console.log(isValidBrackets(null) === false); // Null
    console.log(isValidBrackets(undefined) === false); // Undefined
    console.log(isValidBrackets(123) === false); // Number
    console.log(isValidBrackets({}) === false); // Object
    console.log(isValidBrackets([]) === false); // Array
}

// Run tests
testIsValidBrackets();
```

### Complexity Analysis:

**Time Complexity: O(n)**
- We iterate through the string exactly once
- Each character is processed in constant time (push/pop operations on stack are O(1))
- The lookup in `bracketPairs` is O(1) since it's a simple object property access

**Space Complexity: O(n) in worst case**
- The stack can grow up to the length of the input string
- This happens when all characters are opening brackets (e.g., "((((")
- The `bracketPairs` object is constant space (O(1)) since it doesn't grow with input size
- Non-bracket characters don't affect space usage

### Explanation of Behavior:

1. **Non-bracket characters**: These are completely ignored during validation. Only brackets affect the result.

2. **Empty string**: Considered valid since there are no mismatched brackets.

3. **Non-string inputs**: Return `false` for any input that isn't a string (null, undefined, numbers, objects, etc.).

4. **Stack logic**: 
   - Opening brackets are pushed onto the stack
   - Closing brackets must match the most recent opening bracket (LIFO)
   - If a closing bracket doesn't match the expected one, it's invalid
   - If there are extra closing brackets without corresponding opening ones, it's invalid
   - If there are unclosed opening brackets at the end, it's invalid

5. **Worst-case space**: When the input consists entirely of opening brackets, the stack will store all of them, leading to O(n) space complexity.

This implementation efficiently checks for valid bracket pairs while ignoring non-bracket characters and properly handling edge cases.

I'll implement both iterative and recursive variants of binary search that find the first occurrence of a target in a sorted array.

```js
/**
 * Performs binary search on a sorted array to find the first occurrence of target.
 * Time complexity: O(log n), Space complexity: O(1)
 * @param {Array} sorted - The sorted array to search (must not be modified)
 * @param {*} target - The value to search for
 * @returns {number} The index of the first occurrence of target, or -1 if not found
 * @throws {TypeError} If input is not an array
 */
function binarySearch(sorted, target) {
    if (!Array.isArray(sorted)) {
        throw new TypeError('Input must be an array');
    }

    let left = 0;
    let right = sorted.length - 1;
    let result = -1;

    while (left <= right) {
        const mid = left + Math.floor((right - left) / 2);

        if (sorted[mid] === target) {
            result = mid;
            right = mid - 1; // Continue searching to the left for first occurrence
        } else if (sorted[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    return result;
}

/**
 * Recursive helper function for binary search that finds the first occurrence.
 * Time complexity: O(log n), Space complexity: O(log n) due to recursion stack
 * @param {Array} sorted - The sorted array to search (must not be modified)
 * @param {*} target - The value to search for
 * @param {number} left - The left index of the current search range
 * @param {number} right - The right index of the current search range
 * @returns {number} The index of the first occurrence of target, or -1 if not found
 */
function binarySearchRecursiveHelper(sorted, target, left, right) {
    if (left > right) {
        return -1;
    }

    const mid = left + Math.floor((right - left) / 2);

    if (sorted[mid] === target) {
        // Check if this is the first occurrence
        if (mid === 0 || sorted[mid - 1] !== target) {
            return mid;
        }
        // Continue searching to the left
        return binarySearchRecursiveHelper(sorted, target, left, mid - 1);
    } else if (sorted[mid] < target) {
        return binarySearchRecursiveHelper(sorted, target, mid + 1, right);
    } else {
        return binarySearchRecursiveHelper(sorted, target, left, mid - 1);
    }
}

/**
 * Performs binary search recursively on a sorted array to find the first occurrence of target.
 * Time complexity: O(log n), Space complexity: O(log n) due to recursion stack
 * @param {Array} sorted - The sorted array to search (must not be modified)
 * @param {*} target - The value to search for
 * @returns {number} The index of the first occurrence of target, or -1 if not found
 * @throws {TypeError} If input is not an array
 */
function binarySearchRecursive(sorted, target) {
    if (!Array.isArray(sorted)) {
        throw new TypeError('Input must be an array');
    }

    return binarySearchRecursiveHelper(sorted, target, 0, sorted.length - 1);
}
```

**Documentation:**

1. **Sorted Input Requirement:** Both functions require the input array to be sorted in ascending order. The behavior is undefined if the array is not sorted.

2. **Handling Absent Target:** If the target is not found in the array, both functions return -1.

3. **First Occurrence:** When duplicates exist, both functions return the index of the first occurrence of the target.

4. **Input Validation:** Both functions validate that the input is an array. If not, they throw a TypeError.

5. **Edge Cases:**
   - Empty array: returns -1
   - Single-element array: returns 0 if the element matches, otherwise -1
   - All elements are the same: returns 0
   - Target is smaller than all elements: returns -1
   - Target is larger than all elements: returns -1

6. **Complexity:**
   - Iterative version: O(log n) time, O(1) space
   - Recursive version: O(log n) time, O(log n) space (due to recursion stack)

7. **Midpoint Calculation:** Both implementations use the safe midpoint calculation `left + Math.floor((right - left) / 2)` to avoid potential overflow with large indices.

8. **Input Purity:** Neither function modifies the input array.

The recursive version includes a helper function to maintain the clean interface of the main function while allowing the recursive calls to pass the current search range.

